window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[97]={"id":"097","numero":97,"titre":"Polyradiculonévrites & SLA","objectifs":[{"id":"97-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une polyradiculonévrite","contenu":"<p>Une <span class=\"kw-def\">polyradiculonévrite</span> est une atteinte <span class=\"kw-etio\">inflammatoire</span> diffuse et relativement symétrique touchant <strong>les racines nerveuses</strong> (antérieures motrices et postérieures sensitives) <strong>et les troncs nerveux</strong> situés en aval. Le mécanisme est <span class=\"kw-etio\">auto-immun</span>, <span class=\"kw-def\">démyélinisant</span> ou <span class=\"kw-def\">axonal</span> selon la forme.</p>\n      <p>La topographie est caractéristique : déficit des <strong>4 membres</strong>, symétrique, d'<span class=\"kw-clinique\">évolution</span> <span class=\"kw-clinique\">ascendante</span>, pouvant remonter au tronc, au cou et aux paires crâniennes. La sémiologie associe un déficit <span class=\"kw-clinique\">sensitif</span> et <span class=\"kw-clinique\">moteur</span> avec, comme signe cardinal, une <span class=\"kw-clinique\">aréflexie tendineuse</span> (abolition des ROT dans les territoires déficitaires).</p>\n      <p>Le <span class=\"kw-def\">syndrome de Guillain-Barré</span> en est la forme aiguë typique : extension du déficit en <span class=\"kw-chiffre\">moins de 4 semaines</span>, d'origine <span class=\"kw-etio\">inflammatoire</span> auto-immune.</p>\n      <div class=\"callout callout-warn\">⚠️ Signes négatifs essentiels : <strong>pas de troubles sphinctériens</strong>, pas de niveau sensitif, pas de <span class=\"kw-def\">syndrome pyramidal</span>. Leur présence oriente vers une atteinte médullaire (compression, myélopathie) et <span class=\"kw-alerte\">élimine en pratique le diagnostic de polyradiculonévrite pure</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 96 — Neuropathie périphérique · 92 — <span class=\"kw-clinique\">Déficit moteur</span>-sensitif membres · 91 — Déficit neuro récent</em></p>","frequence":1},{"id":"97-2","rang":"B","rubrique":"Définition","titre":"Connaître les différentes formes de polyradiculonévrites","contenu":"<p>Les polyradiculonévrites aiguës recouvrent plusieurs formes cliniques, distinguées par le mécanisme lésionnel (démyélinisant <span class=\"kw-bio\">vs</span> axonal) et la topographie de l'atteinte.</p>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Contexte / fréquence</th><th>Atteinte</th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>SGB démyélinisant sensitivo-moteur (forme classique)</td>\n            <td>Forme la plus fréquente en Europe</td>\n            <td>Démyélinisation des racines et nerfs périphériques, sensitivo-motrice</td>\n            <td><span class=\"kw-alerte\">Risque d'intubation ⚠️</span> ; phase d'aggravation rapide = mauvais <span class=\"kw-def\">pronostic</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">AMAN</span> — neuropathie axonale motrice aiguë</td>\n            <td>Surtout en Asie, post-<span class=\"kw-etio\">Campylobacter jejuni</span></td>\n            <td>Axonale, <strong>purement motrice</strong></td>\n            <td>Habituellement pas d'<span class=\"kw-ttt\">intubation</span> ; AC anti-<span class=\"kw-bio\">GM1</span> / anti-<span class=\"kw-bio\">GD1a</span> (rang C)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">AMSAN</span> — neuropathie axonale sensitivo-motrice aiguë</td>\n            <td>Rare, forme sévère</td>\n            <td>Axonale avec atteinte sensitive associée</td>\n            <td>Récupération lente</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Syndrome de Miller-Fisher</span> ⭐</td>\n            <td>Variant classique</td>\n            <td>Atteinte oculomotrice + ataxie</td>\n            <td>Triade : <span class=\"kw-clinique\">diplopie non systématisée</span> ; <span class=\"kw-clinique\">ataxie sensorielle</span> ; <span class=\"kw-clinique\">abolition des ROT</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Encéphalite de Bickerstaff</span></td>\n            <td>Forme sévère</td>\n            <td>Tableau encéphalitique</td>\n            <td>Associée à un <span class=\"kw-clinique\">coma</span> dans <span class=\"kw-chiffre\">30 %</span> des cas</td>\n          </tr>\n          <tr>\n            <td>Polyradiculonévrite chronique (<span class=\"kw-etio\">PIDC</span>)</td>\n            <td><span class=\"kw-clinique\">Évolution</span> <span class=\"kw-chiffre\">&gt; 8 semaines</span></td>\n            <td>Démyélinisante chronique</td>\n            <td><span class=\"kw-def\">Diagnostic différentiel</span> temporel — <strong>pas une polyradiculonévrite aiguë</strong></td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-def\">syndrome de Guillain-Barré</span> démyélinisant et les neuropathies axonales aiguës partagent une <span class=\"kw-clinique\">évolution</span> stéréotypée <strong>en 3 phases</strong> (extension, plateau, récupération).</p>\n      <div class=\"callout callout-info\">D'autres pathologies neurologiques atteignent le motoneurone — notamment la <span class=\"kw-etio\">sclérose latérale amyotrophique</span> (SLA, <span class=\"kw-etio\">maladie de Charcot</span>) — mais elles ne sont <strong>pas</strong> des polyradiculonévrites : l'atteinte porte sur le motoneurone et non sur les racines, et le processus n'est pas <span class=\"kw-etio\">inflammatoire</span> au sens immuno-démyélinisant.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 96 — Neuropathie périphérique · 343 — État confusionnel - trouble de conscience</em></p>","frequence":1},{"id":"97-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un syndrome de Guillain-Barré","contenu":"<div class=\"callout callout-warn\">⚠️ Le diagnostic du <span class=\"kw-clinique\">syndrome de Guillain</span>-Barré est <strong>clinique + ENMG</strong> — ces deux éléments suffisent. La <span class=\"kw-bio\">ponction lombaire</span> conforte le diagnostic mais n'est pas indispensable.</div>\n      <p><strong>Présentation clinique princeps.</strong> Début aigu (<span class=\"kw-chiffre\">&lt; 4 semaines</span>, parfois quelques jours) associant des <span class=\"kw-clinique\">paresthésies distales ascendantes</span> aux 4 membres et une parésie symétrique débutant en proximal puis s'étendant en distal. Le déficit touche d'abord les <span class=\"kw-clinique\">membres inférieurs</span>, puis remonte vers le tronc et le cou. L'<span class=\"kw-clinique\">aréflexie tendineuse</span> est quasi constante.</p>\n      <p><strong>Douleurs associées</strong>, souvent évocatrices : <span class=\"kw-clinique\">myalgies</span>, <span class=\"kw-clinique\">radiculalgies des membres inférieurs</span> et <span class=\"kw-clinique\">lombalgies</span>.</p>\n      <p><strong>Atteinte des nerfs crâniens</strong> au <span class=\"kw-def\">stade</span> évolué : <span class=\"kw-clinique\">diplégie faciale</span> (<span class=\"kw-clinique\">paralysie faciale</span> bilatérale — rare hors SGB, argument diagnostique fort) et <span class=\"kw-clinique\">troubles de la déglutition</span>.</p>\n      <p><strong>ENMG des 4 membres et de la face</strong> — examen complémentaire clé (rang C), qui confirme l'atteinte avec la clinique. Les anomalies sont retardées par rapport à la clinique, sans parallélisme avec la sévérité de la paralysie :</p>\n      <table >\n        <thead><tr><th>Temps de l'ENMG</th><th>Anomalies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">EMG</span> de détection</td>\n            <td><span class=\"kw-bio\">Tracés neurogènes</span></td>\n          </tr>\n          <tr>\n            <td>Anomalies initiales</td>\n            <td>Allongement des <span class=\"kw-bio\">ondes F</span> ; allongement des <span class=\"kw-bio\">latences distales</span> (atteinte radiculaire et distale)</td>\n          </tr>\n          <tr>\n            <td>Phase d'état (forme démyélinisante)</td>\n            <td>\n              <strong>Conduction motrice :</strong> <span class=\"kw-bio\">augmentation des latences distales motrices</span> ; <span class=\"kw-bio\">ralentissement des vitesses de conduction</span><br>\n              <strong>Blocs :</strong> <span class=\"kw-bio\">blocs de conduction</span> ; <span class=\"kw-bio\">dispersion des potentiels</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Marqueur pronostique</td>\n            <td><span class=\"kw-alerte\">Inexcitabilité des nerfs = mauvais pronostic</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p>L'<span class=\"kw-imagerie\">IRM médullaire</span> n'est pas nécessaire au diagnostic mais peut montrer un <span class=\"kw-radio\">rehaussement des racines de la queue de cheval en T1 après gadolinium</span> ; elle sert surtout à écarter une cause médullaire.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/97/sgb-irm-rehaussement-racines-1.png\" alt=\"IRM du rachis — rehaussement T1-gadolinium des racines de la queue de cheval au cours d'un syndrome de Guillain-Barré\">\n        <img src=\"../assets/images/97/sgb-irm-rehaussement-racines-2.png\" alt=\"IRM du rachis — prise de contraste des racines nerveuses au cours d'un syndrome de Guillain-Barré\">\n        <figcaption><span class=\"kw-imagerie\">IRM</span> du rachis : rehaussement des racines nerveuses en <span class=\"kw-imagerie\">séquence T1</span> après injection de gadolinium — signe inconstant mais évocateur de polyradiculonévrite aiguë.</figcaption>\n      </figure>\n      <p><strong>Biologie sérique d'accompagnement</strong> (rang C — à connaître pour les distracteurs QCM) :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Anomalie attendue</th><th>Indication / commentaire</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">NFS</span></td><td><span class=\"kw-bio\">Lymphopénie</span></td><td>Manifestation <span class=\"kw-ttt\">biologique</span> aspécifique fréquemment associée</td></tr>\n          <tr><td><span class=\"kw-bio\">Bilan hépatique</span></td><td><span class=\"kw-bio\">↑ transaminases</span> (cytolyse modérée)</td><td><span class=\"kw-def\">Cytolyse hépatique</span> souvent associée</td></tr>\n          <tr><td><span class=\"kw-bio\">Sérologie</span> <span class=\"kw-etio\">Campylobacter jejuni</span></td><td>Positive</td><td>En cas de <span class=\"kw-clinique\">diarrhée</span> récente — oriente vers la forme <strong>AMAN</strong></td></tr>\n          <tr><td><span class=\"kw-bio\">Sérologies</span> virales</td><td>Positives selon contexte</td><td><span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">EBV</span>, séroconversion <span class=\"kw-etio\">VIH</span> (rare) — objectif immunologique</td></tr>\n          <tr><td>AC anti-gangliosides</td><td>Anti-<span class=\"kw-bio\">GM1</span> / anti-<span class=\"kw-bio\">GD1a</span> IgG</td><td>Associés aux formes <strong>AMAN</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ Signes négatifs essentiels : <strong>pas de niveau sensitif, pas de troubles sphinctériens, pas de <span class=\"kw-def\">syndrome pyramidal</span></strong>. Leur présence doit faire évoquer un diagnostic alternatif — <span class=\"kw-etio\">compression médullaire</span>, <span class=\"kw-etio\">myélopathie inflammatoire</span>, ou <span class=\"kw-etio\">sclérose latérale amyotrophique</span> pour une atteinte motrice pure progressive.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 91 — Déficit neuro récent · 92 — <span class=\"kw-clinique\">Déficit moteur</span>-sensitif membres · 98 — Myasthénie · 95 — Radiculalgie - Syndrome canalaire</em></p>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/guillain-barre-syndrome-2","label":"Radiopaedia : Guillain-Barré syndrome"}]},{"id":"97-4","rang":"B","rubrique":"Étiologies","titre":"Connaître l’existence d’évènements déclenchants des polyradiculonévrites","contenu":"<p><span class=\"kw-chiffre\">Plus de 50 %</span> des polyradiculonévrites aiguës sont précédées, de quelques <strong>semaines</strong>, par un <span class=\"kw-clinique\">épisode infectieux respiratoire</span> ou <span class=\"kw-clinique\">digestif</span> — ou plus rarement par une vaccination.</p>\n      <table >\n        <thead><tr><th>Type d'évènement</th><th>Agents / contextes</th><th>Forme favorisée</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Infections virales</td>\n            <td><span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">EBV</span>, <span class=\"kw-etio\">VIH</span> (séroconversion), <span class=\"kw-etio\">Zika</span>, <span class=\"kw-etio\">Chikungunya</span></td>\n            <td>Plutôt formes démyélinisantes</td>\n          </tr>\n          <tr>\n            <td>Infections bactériennes respiratoires</td>\n            <td><span class=\"kw-etio\">Mycoplasma pneumoniae</span></td>\n            <td>Formes démyélinisantes</td>\n          </tr>\n          <tr>\n            <td>Infections digestives</td>\n            <td><span class=\"kw-etio\">Campylobacter jejuni</span> (<span class=\"kw-clinique\">diarrhée</span>)</td>\n            <td>Formes axonales (AMAN ++) — AC anti-<span class=\"kw-bio\">GM1</span> / anti-<span class=\"kw-bio\">GD1a</span></td>\n          </tr>\n          <tr>\n            <td>Vaccinations</td>\n            <td>Cas rares post-vaccinaux décrits</td>\n            <td>Toutes formes — <span class=\"kw-def\">incidence</span> très faible</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">Le mécanisme invoqué est le <span class=\"kw-def\">mimétisme moléculaire</span> : la réaction immunitaire dirigée contre l'agent pathogène cible par erreur des antigènes nerveux partagés (<span class=\"kw-bio\">gangliosides</span>), en particulier dans les formes axonales (anti-<span class=\"kw-bio\">GM1</span>, anti-<span class=\"kw-bio\">GD1a</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — Vaccination</em></p>","frequence":1},{"id":"97-5","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître les trois phases d’évolution d’une polyradiculonévrite","contenu":"<p>Le <span class=\"kw-clinique\">syndrome de Guillain</span>-Barré évolue de façon stéréotypée <strong>en trois phases successives</strong> : extension, plateau, puis récupération.</p>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 256\" role=\"img\" aria-label=\"Frise des trois phases d'évolution d'une polyradiculonévrite, représentées le long d'un axe du temps avec une courbe d'intensité du déficit moteur. Première phase, l'extension, qui dure moins de 4 semaines par définition, parfois seulement quelques jours : aggravation rapide du déficit ascendant et risque respiratoire. Deuxième phase, le plateau, de durée variable allant de quelques jours à plusieurs mois selon la sévérité : déficit maximal stable, aréflexie tendineuse, dysautonomie possible. Troisième phase, la récupération, qui dure plusieurs mois : régression du déficit dans l'ordre inverse de son apparition ; l'absence de récupération au-delà de 12 à 18 mois définit des séquelles définitives, qui touchent environ 15 pour cent des patients, la mortalité étant d'environ 5 pour cent.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\"><span class=\"kw-clinique\">Évolution</span> stéréotypée en 3 phases</text>\n          <text class=\"tx-muted\" x=\"280\" y=\"38\" text-anchor=\"middle\" font-size=\"10.5\">intensité du déficit moteur au fil du temps</text>\n          <rect class=\"fb-amber\" x=\"14\" y=\"52\" width=\"168\" height=\"34\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"98\" y=\"68\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">1 · Extension</text>\n          <text class=\"tx-amber\" x=\"98\" y=\"81\" text-anchor=\"middle\" font-size=\"10\">&lt;<span class=\"kw-chiffre\"> 4 semaines</span> (parfois j)</text>\n          <rect class=\"fb-grey\" x=\"196\" y=\"52\" width=\"168\" height=\"34\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"280\" y=\"68\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">2 · Plateau</text>\n          <text class=\"tx-grey\" x=\"280\" y=\"81\" text-anchor=\"middle\" font-size=\"10\">qq jours → plusieurs mois</text>\n          <rect class=\"fb-ok\" x=\"378\" y=\"52\" width=\"168\" height=\"34\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"462\" y=\"68\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">3 · Récupération</text>\n          <text class=\"tx-ok\" x=\"462\" y=\"81\" text-anchor=\"middle\" font-size=\"10\">plusieurs mois</text>\n          <path d=\"M 30 188 C 90 188 110 108 182 108 L 296 108 C 380 108 400 188 530 188\" fill=\"none\" class=\"ln\" stroke-width=\"2.5\"/>\n          <text class=\"tx-amber\" x=\"98\" y=\"132\" text-anchor=\"middle\" font-size=\"9.5\">aggravation rapide</text>\n          <text class=\"tx-amber\" x=\"98\" y=\"146\" text-anchor=\"middle\" font-size=\"9.5\">déficit ascendant</text>\n          <text class=\"tx-grey\" x=\"280\" y=\"100\" text-anchor=\"middle\" font-size=\"9.5\">déficit maximal · aréflexie</text>\n          <text class=\"tx-ok\" x=\"462\" y=\"132\" text-anchor=\"middle\" font-size=\"9.5\">ordre inverse</text>\n          <text class=\"tx-ok\" x=\"462\" y=\"146\" text-anchor=\"middle\" font-size=\"9.5\">d'apparition</text>\n          <line class=\"ln\" x1=\"22\" y1=\"200\" x2=\"538\" y2=\"200\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"548,200 538,195 538,205\"/>\n          <text class=\"tx-muted\" x=\"538\" y=\"216\" text-anchor=\"end\" font-size=\"10\">temps</text>\n          <rect class=\"fb-red\" x=\"150\" y=\"216\" width=\"260\" height=\"36\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"232\" text-anchor=\"middle\" font-size=\"9.5\">pas de récup à<span class=\"kw-chiffre\"> 12–18 mois</span> = séquelles (~<span class=\"kw-chiffre\">15 %</span>)<tspan x=\"280\" dy=\"12\">· décès ~<span class=\"kw-chiffre\">5 %</span></tspan></text>\n        </svg>\n        <figcaption>Frise des <strong>3 phases</strong> : extension (aggravation, risque respiratoire), plateau (déficit maximal stable), récupération en <strong>ordre inverse</strong> de l'apparition des déficits.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Phase</th><th>Durée</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Extension</span></td>\n            <td><span class=\"kw-chiffre\">&lt; 4 semaines</span> (parfois quelques jours)</td>\n            <td>\n              <strong>Sensitif :</strong> <span class=\"kw-clinique\">paresthésies distales ascendantes</span> aux 4 membres ; myalgies ; <span class=\"kw-clinique\">radiculalgies des membres inférieurs</span> ; lombalgies<br>\n              <strong>Moteur :</strong> <span class=\"kw-clinique\">parésie symétrique</span> débutant en proximal puis distal ; débute aux membres inférieurs ; remonte au tronc et au cou<br>\n              <strong>Gravité :</strong> <span class=\"kw-clinique\">diplégie faciale</span> ; <span class=\"kw-alerte\">aggravation respiratoire rapide</span> = mauvais <span class=\"kw-def\">pronostic</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Plateau</span></td>\n            <td>Variable — de quelques jours à plusieurs mois selon la sévérité</td>\n            <td>\n              <strong>État fonctionnel (par tiers) :</strong> un tiers garde la marche ; un tiers confiné au lit ; un tiers nécessite une assistance respiratoire<br>\n              <strong>Sensitif :</strong> <span class=\"kw-clinique\">ataxie proprioceptive</span><br>\n              <strong>Nerfs crâniens :</strong> <span class=\"kw-clinique\">facial ++</span> (diplégie faciale) ; nerfs bulbaires (<span class=\"kw-clinique\">troubles de la déglutition</span>) ; atteinte oculomotrice plus rare<br>\n              <strong>Végétatif (formes sévères) :</strong> <span class=\"kw-clinique\">hypotension orthostatique</span> ; <span class=\"kw-alerte\">tachycardie ou bradycardie extrême</span> (jusqu'à l'<span class=\"kw-alerte\">asystolie</span>) ; anomalies de la sudation ; <span class=\"kw-clinique\">constipation</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Récupération</span></td>\n            <td>Plusieurs mois (forme démyélinisante) ; rapide ou très lente dans l'<span class=\"kw-etio\">AMAN</span> selon la levée des <span class=\"kw-bio\">blocs de conduction</span> et l'atteinte axonale</td>\n            <td>\n              <strong>Modalité :</strong> récupération dans l'<strong>ordre inverse</strong> de l'apparition des déficits<br>\n              <strong>Délai :</strong> absence de récupération après <span class=\"kw-chiffre\">12 à 18 mois</span> = <span class=\"kw-alerte\">séquelles définitives</span><br>\n              <strong><span class=\"kw-def\">Pronostic</span> :</strong> séquelles définitives <span class=\"kw-chiffre\">~15 %</span> (déficit moteur résiduel, ataxie) ; <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">~5 %</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ À la phase de plateau, l'<span class=\"kw-clinique\">aréflexie tendineuse</span> des territoires déficitaires est <strong>la règle</strong>.</div>","frequence":0},{"id":"97-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les modalités d’interprétation d’une ponction lombaire évocatrice de syndrome de Guillain-Barré","contenu":"<p>Le signe paraclinique cardinal du <span class=\"kw-clinique\">syndrome de Guillain</span>-Barré est la <span class=\"kw-def\">dissociation albumino-cytologique</span> ⭐ : une <span class=\"kw-bio\">hyperprotéinorachie</span> contrastant avec une <span class=\"kw-bio\">cellularité</span> normale du <span class=\"kw-bio\">LCS</span>.</p>\n      <div class=\"callout callout-warn\">⚠️ Il n'y a <strong>pas de parallèle</strong> entre l'<span class=\"kw-clinique\">évolution</span> clinique et l'importance de l'<span class=\"kw-bio\">hyperprotéinorachie</span> — ce n'est pas un marqueur de sévérité.</div>\n      <table >\n        <thead><tr><th>Paramètre du <span class=\"kw-bio\">LCS</span></th><th>Valeur attendue</th><th>Piège / commentaire</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Protéinorachie</td>\n            <td><span class=\"kw-bio\">Hyperprotéinorachie</span>, souvent <span class=\"kw-chiffre\">&gt; 1 g/L</span> (parfois plusieurs g/L)</td>\n            <td>Retardée de <span class=\"kw-chiffre\">3 à 10 jours</span> sur la clinique — <span class=\"kw-alerte\">une PL initiale normale n'élimine pas le diagnostic</span></td>\n          </tr>\n          <tr>\n            <td>Cellularité</td>\n            <td>Réaction cellulaire <span class=\"kw-chiffre\">&lt; 10/mm³</span></td>\n            <td>Une pléiocytose ≥ <span class=\"kw-chiffre\">50/mm³</span> doit faire évoquer un autre diagnostic</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Glycorachie</span></td>\n            <td>Normale</td>\n            <td>Si abaissée → <span class=\"kw-def\">méningite</span> (<span class=\"kw-etio\">bactérienne</span>, <span class=\"kw-etio\">tuberculeuse</span>, <span class=\"kw-etio\">carcinomateuse</span>)</td>\n          </tr>\n          <tr>\n            <td>Cas particulier</td>\n            <td>Étude du <span class=\"kw-bio\">LCS</span> normale dans environ <span class=\"kw-chiffre\">30 %</span> des cas, notamment à la phase précoce</td>\n            <td>Refaire la <span class=\"kw-ttt\">ponction</span> à <span class=\"kw-chiffre\">J7-J10</span> si elle est négative initialement</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ Une pléiocytose <span class=\"kw-chiffre\">&gt; 50/mm³</span> doit faire évoquer une <span class=\"kw-def\">méningoradiculite infectieuse</span> ou une localisation hématologique (<span class=\"kw-def\">lymphome</span>) — <strong>ce n'est pas un <span class=\"kw-clinique\">syndrome de Guillain</span>-Barré typique</strong>.</div>","frequence":2},{"id":"97-7","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes de gravité d’une polyradiculonévrite aiguë et les situations nécessitant une prise en charge en service de réanimation","contenu":"<div class=\"callout callout-danger\">⚠️ <span class=\"kw-alerte\">URGENCE</span> VITALE — toute polyradiculonévrite aiguë impose la recherche répétée de <span class=\"kw-alerte\">signes de gravité</span> respiratoires et dysautonomiques, pour décider à temps du transfert en <span class=\"kw-alerte\">réanimation</span>.</div>\n      <p><strong>1. Signes cliniques d'alerte respiratoire et bulbaire</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Difficultés de toux</span> et <span class=\"kw-clinique\">encombrement bronchique</span></li>\n        <li><span class=\"kw-clinique\">Polypnée</span>, <span class=\"kw-clinique\">respiration paradoxale</span></li>\n        <li><span class=\"kw-clinique\">Troubles de la phonation</span> (atteinte de la musculature bulbaire)</li>\n        <li><span class=\"kw-clinique\">Troubles de la déglutition</span> avec risque de fausses routes</li>\n        <li><span class=\"kw-clinique\">Diplégie faciale</span> et <span class=\"kw-clinique\">aggravation rapide</span> — corrélées à un risque accru de <span class=\"kw-alerte\">détresse</span> respiratoire</li>\n      </ul>\n      <p><span class=\"kw-chiffre\">15 à 30 %</span> des patients seront placés sous <span class=\"kw-ttt\">ventilation assistée</span> — d'où l'importance d'un <span class=\"kw-def\">dépistage</span> répété.</p>\n      <p><strong>2. Signes paracliniques d'alerte</strong></p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Seuil d'alerte</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>PaCO₂</td><td><span class=\"kw-chiffre\">&gt; 45 mmHg</span></td><td><span class=\"kw-alerte\">Indication formelle de VNI</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Capacité vitale</span> forcée (CVF)</td><td><span class=\"kw-chiffre\">&lt; 50 %</span> de la valeur prédite</td><td><span class=\"kw-alerte\">Indication formelle de VNI</span></td></tr>\n          <tr><td>Oxymétrie nocturne</td><td>Désaturations</td><td><span class=\"kw-def\">Surveillance</span> rapprochée + <span class=\"kw-bio\">EFR</span> diurne</td></tr>\n          <tr><td>Troubles de la déglutition</td><td>Fausses routes itératives</td><td>Risque de pneumopathie d'inhalation — <span class=\"kw-ttt\">aspiration / SNG</span>, <span class=\"kw-ttt\">intubation</span> si insuffisant</td></tr>\n        </tbody>\n      </table>\n      <p><strong>3. <span class=\"kw-alerte\">Signes de gravité</span> dysautonomiques</strong></p>\n      <div class=\"callout callout-warn\">⚠️ La dysautonomie des formes sévères justifie une <span class=\"kw-def\">surveillance</span> scopée en <span class=\"kw-alerte\">USI</span> : <span class=\"kw-alerte\">bradycardie extrême pouvant aller jusqu'à l'asystolie</span>, <span class=\"kw-clinique\">hypotension</span> orthostatique, variations tensionnelles brutales.</div>\n      <p><strong><span class=\"kw-def\">Critères de</span> transfert en <span class=\"kw-alerte\">réanimation</span> / USI :</strong> tout signe respiratoire, toute dysautonomie sévère, ou des <span class=\"kw-clinique\">troubles de la déglutition</span> très altérés.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":2},{"id":"97-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge d’un syndrome de Guillain-Barré","contenu":"<div class=\"callout callout-warn\">⚠️ Le traitement spécifique doit être <strong>précoce</strong> : au mieux <span class=\"kw-chiffre\">&lt; 2 semaines</span> après le début des symptômes, fenêtre d'efficacité maximale.</div>\n      <p><strong>Traitements spécifiques</strong> — deux modalités d'efficacité équivalente :</p>\n      <table >\n        <thead><tr><th>Modalité</th><th>Posologie</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Immunoglobulines polyvalentes IV</span></td>\n            <td><span class=\"kw-chiffre\">0,4 g/kg/j</span> pendant <span class=\"kw-chiffre\">5 jours</span></td>\n            <td>\n              <strong>Modalité de référence :</strong> mise en œuvre simple ; pas de voie veineuse centrale ; pas de <span class=\"kw-alerte\">réanimation</span> requise<br>\n              <strong>Tolérance :</strong> <span class=\"kw-clinique\">céphalées</span> ; rares thromboses ; rares insuffisances rénales\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Échanges plasmatiques</span></td>\n            <td><span class=\"kw-chiffre\">4 échanges</span>, un jour sur deux</td>\n            <td>\n              <strong>Indication :</strong> formes sévères en <span class=\"kw-alerte\">USI</span> disposant d'une voie veineuse centrale<br>\n              <strong>Limites :</strong> voie veineuse centrale nécessaire ; complications techniques\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ Les <span class=\"kw-ci\">corticoïdes</span> sont <strong>inutiles</strong> dans le <span class=\"kw-clinique\">syndrome de Guillain</span>-Barré (aucun effet démontré). L'<span class=\"kw-ci\">association IgIV + échanges plasmatiques</span> est inutile — pas de synergie.</div>\n      <p><strong>Effets attendus du traitement :</strong> <span class=\"kw-ttt\">réduction</span> de la durée de ventilation assistée, raccourcissement du délai de reprise de la marche, réduction de la durée d'<span class=\"kw-alerte\">hospitalisation</span>. <span class=\"kw-alerte\">Le pourcentage de séquelles définitives n'est pas modifié</span> par le traitement.</p>\n      <p><strong>Traitement symptomatique et <span class=\"kw-def\">surveillance</span></strong></p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Modalité / indication</th></tr></thead>\n        <tbody>\n          <tr><td>Prévention thromboembolique</td><td><span class=\"kw-ttt\">HBPM</span> systématique chez tout patient alité</td></tr>\n          <tr><td><span class=\"kw-def\">Surveillance</span> respiratoire (phase d'aggravation)</td><td><span class=\"kw-clinique\">Efficacité de la toux</span>, <span class=\"kw-bio\">FR</span>, <span class=\"kw-bio\">capacité vitale</span> mesurée au lit par <span class=\"kw-bio\">spiromètre portable</span> ; <span class=\"kw-bio\">EFR</span> diurne + <span class=\"kw-bio\">oxymétrie nocturne</span> si signes d'alerte</td></tr>\n          <tr><td><span class=\"kw-ttt\">Ventilation mécanique</span></td><td>Si critères respiratoires atteints (<span class=\"kw-chiffre\">PaCO₂ &gt; 45 mmHg</span> ou <span class=\"kw-chiffre\">CVF &lt; 50 %</span>)</td></tr>\n          <tr><td>Contrôle de la <span class=\"kw-clinique\">dysautonomie</span></td><td><span class=\"kw-def\">Surveillance</span> scopée en <span class=\"kw-alerte\">USI</span> ; éviter les <span class=\"kw-alerte\">variations tensionnelles brutales</span> ; surveillance du rythme cardiaque</td></tr>\n          <tr><td>Rééducation et prévention du décubitus</td><td><span class=\"kw-ttt\">Kinésithérapie passive</span> précoce puis active progressive ; <strong>prévention des positions vicieuses</strong> ; prévention des escarres</td></tr>\n          <tr><td>Soutien nutritionnel</td><td><span class=\"kw-ttt\">SNG</span>, voire <span class=\"kw-ttt\">gastrostomie</span> en cas de <span class=\"kw-clinique\">dysphagie</span> prolongée</td></tr>\n          <tr><td>Mesures sociales</td><td>Aide à la reprise du travail, accompagnement de la convalescence</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><span class=\"kw-def\">Pronostic</span> : mortalité globale <span class=\"kw-chiffre\">~5 %</span> ; séquelles définitives <span class=\"kw-chiffre\">~15 %</span> (<span class=\"kw-clinique\">déficit moteur</span> résiduel, ataxie) ; les récidives sont <span class=\"kw-alerte\">très rares</span>.</div>\n      <p><strong>Facteurs de mauvais <span class=\"kw-def\">pronostic</span> :</strong> âge <span class=\"kw-chiffre\">&gt; 60 ans</span> ; phase d'aggravation très rapide ; diplégie faciale initiale ; inexcitabilité des nerfs à l'ENMG ; ventilation prolongée.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":2}],"astuces":[{"type":"danger","titre":"GBS vs SLA — le discriminant absolu","contenu":"<strong>SGB :</strong> parésie flasque <strong>ascendante</strong> + <strong>aréflexie</strong> + signes <strong>sensitifs</strong> + atteinte des <strong>nerfs crâniens</strong> (diplégie faciale). <strong>SLA :</strong> atteinte motrice <strong>pure</strong> + <strong>fasciculations</strong> + signes <strong>pyramidaux</strong> (Babinski, Hoffman, spasticité) + <strong>sensibilité intacte</strong>. L'<strong>ENMG</strong> tranche : tracé de dénervation active + sensibilité normale = SLA."},{"type":"tip","titre":"Le syndrome de Miller-Fisher en 3 mots","contenu":"<strong>Triade :</strong> <span class=\"kw-clinique\">ophtalmoplégie bilatérale</span> (diplopie non systématisée) + <span class=\"kw-clinique\">ataxie sensorielle</span> + <span class=\"kw-clinique\">abolition des ROT</span>. Anticorps anti-<span class=\"kw-bio\">GQ1b</span>. Pas d'atteinte des membres. À ne pas confondre avec un SGB classique."},{"type":"info","titre":"Dissociation albumino-cytologique — le mnémo officiel","contenu":"<strong>« St Pierre est DéCédé »</strong> : <strong>S</strong>yndrome de Guillain-Barré, <strong>P</strong>oliomyélite, <strong>É</strong>tat de maladie (méningite TB), <strong>D</strong>émyélinisation, <strong>C</strong>ompression médullaire, <strong>D</strong>iabète. Hyperprotéinorachie > 1 g/L + pléiocytose < 10/mm³ (retardée de 3–10 jours)."},{"type":"warn","titre":"Jamais de corticoïdes dans le SGB","contenu":"Les <strong>corticoïdes sont inutiles</strong> dans le syndrome de Guillain-Barré et peuvent être délétères. Le traitement est <strong>IgIV</strong> (0,4 g/kg × 5 jours) ou <strong>échanges plasmatiques</strong> (4 échanges). Par contre, les corticoïdes <strong>sont efficaces dans la CIDP</strong> (chronique) — le timing d'évolution fait toute la différence."},{"type":"danger","titre":"Hyponatrémie et hallucinations dans le SGB","contenu":"Le SGB peut s'accompagner d'un <strong>SIADH</strong> → hyponatrémie + troubles de la conscience / hallucinations. Trois causes d'hallucinations à connaître : <strong>delirium tremens</strong> (alcool), <strong>hallucinations liées au SGB lui-même</strong> (auto-immune), <strong>hyponatrémie sur SIADH</strong>. Correction de l'hyponatrémie lente pour éviter le myélinolyse centropontine."}],"strategie":{"urgence":"<p>Le SGB est une <strong><span class=\"kw-alerte\">urgence</span> neurologique</strong> : la <span class=\"kw-alerte\">menace</span> vitale est <span class=\"kw-alerte\">respiratoire</span> et <span class=\"kw-alerte\">dysautonomique</span>. <span class=\"kw-chiffre\">15 à 30 %</span> des patients sont placés sous ventilation assistée. Tout <span class=\"kw-alerte\">signe de gravité</span> impose le transfert en <span class=\"kw-alerte\">soins intensifs</span>.</p><ul><li>Atteinte de la musculature bulbaire : troubles de la <span class=\"kw-clinique\">déglutition</span> ou de la <span class=\"kw-clinique\">phonation</span></li><li><span class=\"kw-alerte\">Diplégie faciale</span> + <span class=\"kw-alerte\">aggravation rapide</span> → risque accru de <span class=\"kw-alerte\">détresse</span> respiratoire</li><li>Critères respiratoires : <span class=\"kw-chiffre\">CVF &lt; 50 %</span> de la prédite ou <span class=\"kw-chiffre\">PaCO₂ &gt; 45 mmHg</span></li><li>Dysautonomie : variations tensionnelles, troubles du rythme (<span class=\"kw-alerte\">bradycardie</span> jusqu'à l'<span class=\"kw-alerte\">asystolie</span>)</li><li>Perte de la marche autonome / confinement au lit</li></ul>","principes":"<p>À débuter <strong>précocement</strong>, au mieux <span class=\"kw-chiffre\">&lt; 2 semaines</span> après les premiers symptômes. Deux modalités d'<strong>efficacité équivalente</strong> — on en choisit <strong>une seule</strong>.</p>","suivi":"<p><strong>Phase d'aggravation :</strong> <span class=\"kw-def\">dépistage</span> des troubles de la <span class=\"kw-clinique\">déglutition</span> et des difficultés <span class=\"kw-clinique\">respiratoires</span> — efficacité de la <span class=\"kw-clinique\">toux</span>, <span class=\"kw-bio\">FR</span>, <span class=\"kw-bio\">capacité vitale</span> au spiromètre portable au lit.<br><strong>Phase de plateau :</strong> troubles végétatifs (<span class=\"kw-clinique\">rythme cardiaque</span>, variations tensionnelles) et complications du décubitus (<span class=\"kw-alerte\">TVP</span>, positions vicieuses).<br><strong>Seuil de transfert :</strong> tout risque de <span class=\"kw-alerte\">décompensation</span> respiratoire, infectieuse ou dysautonomique → <span class=\"kw-alerte\">unité de soins intensifs</span>.</p>","redflags":"<p><span class=\"kw-clinique\">Évolution</span> en <strong>3 phases</strong> (extension &lt; 4 sem, plateau, récupération en ordre inverse). Récupération possible sur plusieurs mois ; absence de récupération à <span class=\"kw-chiffre\">12-18 mois</span> = séquelles définitives. <span class=\"kw-def\">Mortalité</span> <span class=\"kw-chiffre\">~5 %</span>, séquelles définitives <span class=\"kw-chiffre\">~15 %</span> ; les <strong>récidives sont très rares</strong>.</p><ul><li>Âge <span class=\"kw-chiffre\">&gt; 60 ans</span></li><li>Phase d'aggravation très rapide</li><li><span class=\"kw-alerte\">Atteinte faciale bilatérale</span> initiale</li><li><span class=\"kw-alerte\">Inexcitabilité des nerfs</span> à l'ENMG</li><li>Ventilation prolongée</li></ul>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/radiculalgies-et-syndromes-canalaires-neuropathies-peripheriques-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre","label":"Collège CEN — PRN aiguë / Guillain-Barré"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/33.%20Paralysies%20extensives.pdf","label":"Collège Réa CE-MIR — Paralysies extensives (PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Polyradiculonévrite aiguë suspectée — Déficit moteur ascendant bilatéral + aréflexie + paresthésies distales, installation < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> semaines</span>","detail":"<h4>CAT devant une suspicion de <span class=\"kw-clinique\">syndrome de Guillain</span>-Barré — Confirmer le diagnostic, puis laisser les <span class=\"kw-alerte\">signes de gravité</span> dicter le lieu de prise en charge</h4>","branches":[{"to":"t-autre","label":"Drapeau rouge : troubles sphinctériens, niveau sensitif net, ou pléiocytose LCS > 50/mm³","color":"amber"},{"to":"q-gravite","label":"Tableau compatible : clinique + ENMG (ondes F, blocs) + PL = dissociation albumino-cytologique","color":"green"}]},{"id":"t-autre","kind":"terminal","label":"Reconsidérer le diagnostic","color":"amber","detail":"<h4>Pièges</h4><ul><li><span class=\"kw-alerte\">Troubles sphinctériens</span> ou <span class=\"kw-alerte\">niveau sensitif net</span> → compression médullaire / myélite</li><li>Pléiocytose <span class=\"kw-bio\">LCS</span> <span class=\"kw-chiffre\">&gt; 50/mm³</span> → évoquer une méningoradiculite infectieuse</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">IRM médullaire</span> en <span class=\"kw-alerte\">urgence</span> ; ne pas étiqueter « Guillain-Barré » tant que ces drapeaux ne sont pas levés.</li></ul>"},{"id":"q-gravite","kind":"decision","label":"Rechercher des signes de gravité — Atteinte bulbaire, respiratoire, dysautonomie","branches":[{"to":"t-rea","label":"≥ 1 signe de gravité : déglutition/phonation, CVF < 50 % ou PaCO₂ > 45, dysautonomie, diplégie faciale + aggravation rapide","color":"red"},{"to":"t-hospit","label":"Aucun signe de gravité : marche et respiration conservées","color":"green"}]},{"id":"t-rea","kind":"terminal","label":"Réanimation / soins intensifs","color":"red","detail":"<h4>Support vital</h4><ul><li>Ventilation : <span class=\"kw-ttt\">VNI</span> puis <span class=\"kw-ttt\">IOT</span> si <span class=\"kw-chiffre\">CVF &lt; 50 %</span> ou <span class=\"kw-chiffre\">PaCO₂ &gt; 45 mmHg</span></li><li>Scope de la <span class=\"kw-clinique\">dysautonomie</span> (variations tensionnelles, <span class=\"kw-alerte\">bradycardie/asystolie</span>)</li><li>Prévention du décubitus (<span class=\"kw-ttt\">HBPM</span>)</li></ul><h4>Traitement spécifique</h4><ul><li><span class=\"kw-ttt\">IgIV 0,4 g/kg/j × 5 j</span> (préférées) OU <span class=\"kw-ttt\">4 échanges plasmatiques</span> 1j/2</li><li>Au mieux <span class=\"kw-chiffre\">&lt; 2 semaines</span> ; <span class=\"kw-ci\">PAS de corticoïdes</span>, <span class=\"kw-ci\">PAS d'association</span></li></ul>"},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation conventionnelle + surveillance rapprochée","color":"green","detail":"<h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Déglutition + paramètres respiratoires (<span class=\"kw-clinique\">toux</span>, <span class=\"kw-bio\">FR</span>, <span class=\"kw-bio\">capacité vitale</span> au spiromètre)</li><li>Transfert en <span class=\"kw-alerte\">USI</span> au moindre signe de <span class=\"kw-alerte\">décompensation</span></li></ul><h4>Traitement spécifique</h4><ul><li><span class=\"kw-ttt\">IgIV 0,4 g/kg/j × 5 j</span> OU <span class=\"kw-ttt\">échanges plasmatiques</span> (4, 1j/2), <span class=\"kw-chiffre\">&lt; 2 sem</span></li><li><span class=\"kw-ttt\">Rééducation</span> précoce</li></ul><h4><span class=\"kw-clinique\">Évolution</span></h4><ul><li>3 phases (extension &lt; 4 sem, plateau, récupération en ordre inverse). Séquelles <span class=\"kw-chiffre\">~15 %</span>, décès <span class=\"kw-chiffre\">~5 %</span>.</li></ul><h4>Renvoi</h4><ul><li>359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</li></ul>"}]},"cards":[]};